import{c as a,Q as s,j as e,m as n}from"./chunks/framework.t4rEqR7d.js";const c=JSON.parse('{"title":"桌面端","description":"","frontmatter":{},"headers":[],"relativePath":"zh/desktop.md","filePath":"zh/desktop.md"}'),o={name:"zh/desktop.md"};function i(r,t,d,l,p,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="桌面端" tabindex="-1">桌面端 <a class="header-anchor" href="#桌面端" aria-label="Permalink to &quot;桌面端&quot;">​</a></h1><p>语言：中文 | <a href="/pagent/desktop.html">English</a></p><p><strong>pagent Desktop</strong> 是在电脑上使用的 AI 助手工作台：左侧看历史会话，中间对话，右侧看沙箱里的文件和生成物（网页、PDF 等）。</p><p>本文面向<strong>普通用户</strong>——下载安装、配置 Key、创建第一个任务、日常怎么用。若要改桌面端代码，请看仓库里的 <a href="https://github.com/SyncLionPaw/pagent/blob/main/editors/desktop/README.md" target="_blank" rel="noreferrer">开发者 README</a>。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><h3 id="_1-安装后端-必做" tabindex="-1">1. 安装后端（必做） <a class="header-anchor" href="#_1-安装后端-必做" aria-label="Permalink to &quot;1. 安装后端（必做）&quot;">​</a></h3><p>桌面端需要本机有 <code>pagent</code> 命令（和 VS Code 插件一样）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p>若之后提示无法启动后端，确认终端里能运行 <code>pagent</code>，或重新执行上面的安装命令。</p><p>还没有 <code>uv</code>？可先按 <a href="./guide/install.html">安装指南</a> 装好 Python 环境，再执行 <code>uv tool install pagent</code>。</p><h3 id="_2-下载桌面应用" tabindex="-1">2. 下载桌面应用 <a class="header-anchor" href="#_2-下载桌面应用" aria-label="Permalink to &quot;2. 下载桌面应用&quot;">​</a></h3><p>在 <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a> 下载桌面端：</p><ul><li><strong>macOS（Apple 芯片）</strong> — <code>pagent-Desktop-&lt;版本号&gt;-arm64.zip</code>，或资源里的 <code>pagent Desktop.app</code>。</li></ul><p>解压后把 <strong>pagent Desktop</strong> 拖进「应用程序」文件夹。</p><h3 id="macos-提示「已损坏-无法打开」" tabindex="-1">macOS 提示「已损坏，无法打开」？ <a class="header-anchor" href="#macos-提示「已损坏-无法打开」" aria-label="Permalink to &quot;macOS 提示「已损坏，无法打开」？&quot;">​</a></h3><p>从 GitHub 下载的 zip 会带系统<strong>隔离标记</strong>，未签名应用常被误报为「已损坏」——<strong>不是包坏了</strong>。</p><p><strong>推荐</strong>：打开「终端」，执行（安装路径默认如下）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -cr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/Applications/pagent Desktop.app&quot;</span></span></code></pre></div><p>然后双击打开。zip 里也有 <strong><code>打开说明.txt</code></strong>。</p><p>若只是首次拦截，也可试 <strong>右键应用 → 打开 → 仍要打开</strong>（对「已损坏」提示有时无效，优先用上面的 <code>xattr</code>）。</p><p><strong>Windows / Linux</strong> 安装包暂未发布，可先用 <a href="./vscode.html">VS Code 插件</a> 或终端命令 <code>pagent</code>。</p><h2 id="发第一条消息前-配置-api-key" tabindex="-1">发第一条消息前：配置 API Key <a class="header-anchor" href="#发第一条消息前-配置-api-key" aria-label="Permalink to &quot;发第一条消息前：配置 API Key&quot;">​</a></h2><p><strong>首次打开</strong>若尚未安装 pagent 或未配置 API Key，会强制弹出 <strong>首次设置</strong>（三步：环境 → API Key → 沙箱），完成前无法使用主界面。配置齐全后可在用户菜单再次打开向导。设置页里的 <strong>环境自检</strong> 是另一块：用来诊断状态与磁盘占用，不是向导。</p><p>引导会检测：</p><ul><li><code>uv</code> / <code>pagent</code> 是否在 PATH（可一键 <code>uv tool install pagent</code> 或复制命令）</li><li>是否已配置 API Key（可写入 <code>~/.pagent/pagent.toml</code>）</li><li>可选：<code>docker</code> / <code>podman</code> 与 <code>pagent:latest</code> 镜像（仅 container 沙箱需要）</li></ul><p>点 <strong>稍后配置</strong> 可跳过；之后发消息前仍需自行配置 Key。</p><p>若未走引导，请任选一种方式配置 Key：</p><p><strong>环境变量：</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><p><strong>配置文件（推荐）：</strong> 新建 <code>~/.pagent/pagent.toml</code>：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span></code></pre></div><p>更多模型说明见 <a href="./guide/providers.html">模型与 API Key</a>。</p><p>若未配置，发送消息后会出现错误提示。标题栏 <strong>设置</strong>（齿轮）可进行 <strong>环境自检</strong>（状态灯 + <code>~/.pagent</code> / 镜像磁盘占用）并查看 <code>pagent.toml</code> 概览；配置内容需在文本编辑器中修改。</p><h2 id="第一次打开" tabindex="-1">第一次打开 <a class="header-anchor" href="#第一次打开" aria-label="Permalink to &quot;第一次打开&quot;">​</a></h2><ol><li>启动 <strong>pagent Desktop</strong>。</li><li>应用会自动拉起后端，并尝试<strong>恢复当前项目下最近一条会话</strong>。</li><li>想从新对话开始，点侧栏 <strong>新建任务</strong>。</li></ol><h3 id="新建任务" tabindex="-1">新建任务 <a class="header-anchor" href="#新建任务" aria-label="Permalink to &quot;新建任务&quot;">​</a></h3><p>在 <strong>新建任务</strong> 对话框里：</p><table tabindex="0"><thead><tr><th>项</th><th>建议</th></tr></thead><tbody><tr><td><strong>沙箱类型</strong></td><td>选 <strong>local</strong>（本机运行，默认即可，无需 Docker）</td></tr><tr><td><strong>项目目录</strong></td><td>选要让助手操作的那个文件夹</td></tr></tbody></table><p>点 <strong>创建会话</strong>，在底部输入框打字，<strong>Enter</strong> 发送（<strong>Shift+Enter</strong> 换行）。</p><h2 id="界面说明" tabindex="-1">界面说明 <a class="header-anchor" href="#界面说明" aria-label="Permalink to &quot;界面说明&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────┬──────────────────────┬─────────────┐</span></span>
<span class="line"><span>│  会话列表   │        对话          │ 文件与生成物 │</span></span>
<span class="line"><span>└─────────────┴──────────────────────┴─────────────┘</span></span></code></pre></div><ul><li><strong>左侧</strong> — 历史会话，点一条可继续聊。</li><li><strong>中间</strong> — 对话内容、工具步骤、输入框。</li><li><strong>右侧</strong> — 沙箱目录、项目文件、生成物预览、日志。</li></ul><p>可拖动中间分隔条调宽度。<strong>⌘K</strong> 或标题栏 <strong>?</strong> 查看快捷键。</p><h2 id="输入框" tabindex="-1">输入框 <a class="header-anchor" href="#输入框" aria-label="Permalink to &quot;输入框&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td><strong>发送 / 停止</strong></td><td>发送消息；运行中变为 <strong>停止</strong>，可取消当前任务</td></tr><tr><td><strong>闪电（YOLO）</strong></td><td>自动批准工具调用——仅在完全信任当前任务时开启</td></tr><tr><td><strong>圆环</strong></td><td>上下文用量的大致比例</td></tr><tr><td><strong>@</strong></td><td>把项目或沙箱里的文件路径插入到消息里</td></tr></tbody></table><h2 id="设置与帮助" tabindex="-1">设置与帮助 <a class="header-anchor" href="#设置与帮助" aria-label="Permalink to &quot;设置与帮助&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>作用</th></tr></thead><tbody><tr><td><strong>齿轮</strong></td><td>环境自检（状态灯 + 磁盘占用）+ 查看 <code>pagent.toml</code></td></tr><tr><td><strong>书本图标</strong></td><td>在浏览器打开本文档站</td></tr><tr><td><strong>用户菜单 → 扫码看文档</strong></td><td>手机扫码阅读文档</td></tr></tbody></table><p>改模型或高级沙箱选项，请用文本编辑器改 <code>pagent.toml</code>。</p><h2 id="文件存在哪" tabindex="-1">文件存在哪 <a class="header-anchor" href="#文件存在哪" aria-label="Permalink to &quot;文件存在哪&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span>
<span class="line"><span>├── pagent.toml       # API Key 与模型</span></span>
<span class="line"><span>├── threads/          # 会话记录</span></span>
<span class="line"><span>└── skills/           # 可选本地 skills</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;你的项目&gt;/</span></span>
<span class="line"><span>└── artifacts/        # 助手生成的文件（网页等）</span></span></code></pre></div><p>不要把含真实 Key 的 <code>pagent.toml</code> 发给别人或提交到 Git。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可以试试</th></tr></thead><tbody><tr><td><strong>「已损坏，无法打开」</strong></td><td>终端：<code>xattr -cr &quot;/Applications/pagent Desktop.app&quot;</code></td></tr><tr><td>后端 / Bridge 起不来</td><td>执行 <code>uv tool install pagent</code>；看右侧日志</td></tr><tr><td>发送后报错</td><td>检查 <code>pagent.toml</code> 或 <code>DEEPSEEK_API_KEY</code></td></tr><tr><td>设置里写「还没有配置文件」</td><td>按上文创建 <code>~/.pagent/pagent.toml</code></td></tr><tr><td>工具一直显示「运行中」</td><td>点 <strong>停止</strong> 或重新发消息；新版本重开会自动修复</td></tr></tbody></table><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./vscode.html">VS Code 插件</a> — 在 VS Code 里用，首次有 Key 引导</li><li><a href="./guide/install.html">安装指南</a> — 还没有 <code>uv</code> 时从这里开始</li></ul>`,55)])])}const k=a(o,[["render",i]]);export{c as __pageData,k as default};
